INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (175, 1, '변수 치환의 우선순위', 'compose 파일에 `GREETING: ${GREETING:-hello-default}` 라고 썼습니다. `.env` 파일에 `GREETING=from-dotenv` 가 있고, 쉘에서 `GREETING=from-shell docker compose config` 를 실행하면 어떤 값이 쓰일까요?', '쉘 환경 변수가 가장 우선이에요.', NULL, NULL, '[]', 'choice', '["`.env` 파일이 항상 쉘 변수보다 우선한다", "기본값이 항상 가장 우선한다", "쉘 환경 변수(`from-shell`)가 가장 우선이고, 그다음이 `.env` 파일(`from-dotenv`), 둘 다 없을 때만 `:-` 뒤의 기본값(`hello-default`)이 쓰인다", "쉘 변수와 `.env` 값이 이어 붙는다"]', 2, '`docker compose config` 로 치환된 최종 값을 미리 볼 수 있습니다. `.env` 는 compose 파일을 실행하는 폴더(프로젝트 폴더)에 둡니다.', NULL, NULL, NULL, NULL),
  (175, 2, '필수 변수 표시', 'compose 파일에 `command: ["echo","${MUSTHAVE:?MUSTHAVE is required}"]` 라고 쓰고 `MUSTHAVE` 를 정하지 않은 채 `docker compose config` 를 하면 어떻게 될까요?', '`:?` 는 값이 없으면 멈추라는 뜻이에요.', NULL, NULL, '[]', 'choice', '["빈 문자열로 치환되어 정상 실행된다", "`required variable MUSTHAVE is missing a value: MUSTHAVE is required` 같은 오류로 멈춘다 (`:-` 는 기본값을 쓰고, `:?` 는 오류로 멈춘다)", "기본값 `MUSTHAVE` 가 쓰인다", "경고만 나오고 컨테이너가 시작된다"]', 1, '실수로 변수를 빠뜨려 빈 값으로 배포되는 사고를 막아 줍니다.', NULL, NULL, NULL, NULL),
  (175, 3, 'environment 와 env_file', '서비스에 `env_file: app.env`(`FROM_BOTH=from-env-file`, `ONLY_FILE=file-only`)와 `environment` 의 `FROM_BOTH: from-environment` 를 함께 썼습니다. 컨테이너 안의 `FROM_BOTH` 와 `ONLY_FILE` 은 무엇일까요? `docker compose run -e FROM_BOTH=from-run` 으로 실행하면요?', '파일 목록보다 직접 쓴 값이 우선이에요.', NULL, NULL, '[]', 'choice', '["`FROM_BOTH` 는 `from-environment`(`environment` 가 `env_file` 보다 우선), `ONLY_FILE` 은 `file-only`(파일에만 있는 값도 들어간다)이고, `run -e` 로 실행하면 그 값(`from-run`)으로 덮어쓴다", "`FROM_BOTH` 는 `from-env-file` 이고 `ONLY_FILE` 은 비어 있다", "두 값이 이어 붙은 `from-environment from-env-file` 이다", "`run -e` 는 `environment` 값을 바꾸지 못한다"]', 0, '`.env` 는 compose 파일의 `${}` 치환에 쓰이고, 컨테이너 환경 변수는 `environment` 와 `env_file` 로 정합니다.', NULL, NULL, NULL, NULL),
  (175, 4, 'depends_on 의 기본 동작', '`early` 서비스가 `depends_on: [db]` 만 쓰고, `db` 는 준비되는 데 4~5초가 걸립니다. `docker compose up -d` 를 하면 `early` 는 언제 시작될까요?', '기본은 시작 순서만 지켜요.', NULL, NULL, '[]', 'choice', '["`db` 가 healthy 가 될 때까지 기다렸다가 시작된다", "`db` 보다 먼저 시작된다", "`db` 가 종료될 때까지 기다린다", "`db` 컨테이너가 시작된 직후(약 1초 뒤)에 시작된다. 기본 `depends_on` 은 시작 순서만 지키고 `db` 가 준비(healthy)될 때까지 기다리지 않는다"]', 3, '앱이 시작하자마자 DB 에 접속하면 실패할 수 있습니다. 준비를 기다리려면 `condition: service_healthy` 를 쓰세요.', NULL, NULL, NULL, NULL),
  (175, 5, 'service_healthy', '`late` 서비스가 `depends_on` 의 `db` 에 `condition: service_healthy` 를 썼고 `db` 에 healthcheck 가 있습니다. `late` 는 언제 시작될까요?', 'healthcheck 가 통과할 때까지 기다려요.', NULL, NULL, '[]', 'choice', '["`db` 가 시작되는 즉시 같이 시작된다", "`db` 가 실패할 때까지 기다린다", "`db` 의 healthcheck 가 통과해 `healthy` 가 된 뒤에 시작된다 (이 예에서는 `db` 보다 약 5초 늦게 시작되었다)", "healthcheck 와 상관없이 항상 10초 뒤에 시작된다"]', 2, '`docker compose ps` 의 STATUS 에서 `(healthy)` 로 확인합니다.', NULL, NULL, NULL, NULL),
  (175, 6, 'profiles', '`tool` 서비스에 `profiles: [debug]` 를 썼습니다. 그냥 `docker compose up -d` 를 하면 `tool` 은 어떻게 될까요? 어떻게 켜나요?', '특정 상황에서만 켜는 서비스예요.', NULL, NULL, '[]', 'choice', '["항상 함께 시작된다", "프로파일을 켜지 않으면 `tool` 은 시작되지 않고 `docker compose ps` 에도 보이지 않는다. `--profile debug` 옵션이나 `COMPOSE_PROFILES=debug` 환경 변수로 켠다", "`profiles` 는 compose 에서 지원하지 않는 필드이다", "`tool` 이 삭제된다"]', 1, '`docker compose config --services` 는 기본 서비스 목록만, `COMPOSE_PROFILES=debug` 를 주면 `tool` 도 함께 보여 줍니다.', NULL, NULL, NULL, NULL),
  (175, 7, '서비스 이름을 지정해 올리기', '`docker compose --profile debug up -d tool` 처럼 `up` 뒤에 서비스 이름 `tool` 을 쓰면 어떻게 될까요?', '이름을 쓰면 그 서비스만 대상이에요.', NULL, NULL, '[]', 'choice', '["그 서비스(`tool`)의 컨테이너만 만들고 시작한다 (출력에 `tool` 의 `Creating`, `Created`, `Starting`, `Started` 줄만 나온다). 이름을 쓰지 않으면 기본 프로파일의 모든 서비스가 대상이다", "이름을 써도 항상 모든 서비스가 시작된다", "`tool` 이라는 새 프로젝트가 만들어진다", "오류가 나서 아무것도 시작되지 않는다"]', 0, '필요한 서비스만 올려 보며 확인할 때 편합니다.', NULL, NULL, NULL, NULL),
  (175, 8, '프로젝트와 이름 규칙', '프로젝트 이름을 `-p etudev175` 로 정하고 서비스 `db` 를 올렸습니다. 컨테이너와 기본 네트워크 이름은 어떻게 만들어질까요?', '프로젝트, 서비스, 번호를 이어 붙여요.', NULL, NULL, '[]', 'choice', '["컨테이너는 `db`, 네트워크는 `bridge` 이다", "컨테이너는 `db_etudev175_1` 이다", "이름은 무작위로 만들어진다", "컨테이너는 `etudev175-db-1` (프로젝트-서비스-번호), 기본 네트워크는 `etudev175_default` 이다. 컨테이너에는 `com.docker.compose.project` 같은 라벨도 붙는다"]', 3, '`docker compose ls` 로 프로젝트 목록을 봅니다.', NULL, NULL, NULL, NULL),
  (175, 9, '--scale', '`docker compose up -d --scale early=3` 을 하면 어떻게 될까요? 다시 `--scale early=1` 로 하면요?', '같은 서비스를 여러 개 띄워요.', NULL, NULL, '[]', 'choice', '["`early` 서비스가 3번 다시 시작된다", "`early-1` 이 3개로 복제되어 이름이 같다", "`early` 서비스의 컨테이너가 3개(`early-1`, `early-2`, `early-3`)로 늘어나고, `--scale early=1` 로 하면 1개로 줄어든다", "`--scale` 은 `up` 에서 쓸 수 없다"]', 2, '`docker compose ps` 로 늘어난 컨테이너 이름을 확인하세요.', NULL, NULL, NULL, NULL),
  (175, 10, 'compose run', '`docker compose run --rm early echo one-off` 와 `--rm` 없이 실행한 경우는 무엇이 다를까요?', '일회성 컨테이너예요.', NULL, NULL, '[]', 'choice', '["`run` 은 서비스를 영구히 늘린다", "서비스 설정으로 일회성 컨테이너(`프로젝트-early-run-해시`)를 만들어 명령을 실행하고, `--rm` 이면 끝난 뒤 삭제되고 `--rm` 이 없으면 `Exited` 상태로 남는다", "`--rm` 이 없으면 명령이 실행되지 않는다", "`run` 은 compose 파일을 수정한다"]', 1, '남은 일회성 컨테이너는 고아 컨테이너 경고에 나타날 수 있습니다. `docker compose ps -a` 로 확인해 지우세요.', NULL, NULL, NULL, NULL),
  (175, 11, 'up 을 다시 하면', '실행 중인 프로젝트에서 `docker compose up -d` 를 다시 실행했습니다. 아무것도 바꾸지 않았을 때와 한 서비스의 `command` 를 바꿨을 때는 각각 어떻게 될까요?', '바뀐 서비스만 다시 만들어요.', NULL, NULL, '[]', 'choice', '["바꾸지 않았으면 `Running` 으로 그대로 두고, 바꾼 서비스만 `Recreate` → `Recreated` 로 다시 만든다. `--force-recreate` 를 붙이면 변경이 없어도 다시 만든다", "항상 모든 서비스를 다시 만든다", "변경해도 `down` 하기 전에는 반영되지 않는다", "오류로 실패한다"]', 0, '설정을 바꾼 뒤에는 `up -d` 만 다시 하면 필요한 서비스만 교체됩니다.', NULL, NULL, NULL, NULL),
  (175, 12, '고아 컨테이너', 'compose 파일에서 서비스 하나를 지운 뒤 `docker compose up -d` 를 하면 어떤 일이 생길까요? 어떻게 정리할까요?', '파일에는 없지만 프로젝트에 남은 컨테이너예요.', NULL, NULL, '[]', 'choice', '["경고 없이 자동으로 모두 삭제된다", "`up` 이 실패한다", "고아 컨테이너는 다음 재부팅 때 사라진다", "`Found orphan containers ...` 경고가 나온다 (그 컨테이너는 자동으로 지워지지 않는다). `docker compose down --remove-orphans` 로 정리한다"]', 3, '`docker compose run` 으로 남은 일회성 컨테이너도 고아로 보고될 수 있습니다.', NULL, NULL, NULL, NULL),
  (175, 13, 'config --services', '`docker compose config --services` 를 기본으로 실행했을 때와 `COMPOSE_PROFILES=debug` 를 주고 실행했을 때 목록은 어떻게 다를까요?', '프로파일이 켜지면 서비스가 늘어요.', NULL, NULL, '[]', 'choice', '["두 경우 목록이 같다", "기본에서 모든 서비스가 나오고 `debug` 를 주면 줄어든다", "기본은 프로파일이 없는 서비스(`db early envsvc late`)만 나오고, `COMPOSE_PROFILES=debug` 를 주면 `tool` 까지 나온다", "`config --services` 는 컨테이너 이름을 보여 준다"]', 2, '실제로 올리기 전에 어떤 서비스가 켜질지 확인하는 데 씁니다.', NULL, NULL, NULL, NULL),
  (175, 14, 'compose ls', '`docker compose ls` 는 무엇을 보여 줄까요?', '프로젝트 단위의 목록이에요.', NULL, NULL, '[]', 'choice', '["모든 이미지 목록", "실행 중인 compose 프로젝트들의 이름과 상태(서비스 수)를 보여 준다 (`docker compose ps` 는 한 프로젝트의 컨테이너를 보여 준다)", "모든 볼륨 목록", "한 서비스의 로그"]', 1, '여러 프로젝트를 올려 둔 서버에서 어떤 프로젝트가 떠 있는지 확인할 때 씁니다.', NULL, NULL, NULL, NULL),
  (175, 15, '기본값 문법', '변수가 없을 때 쓸 **기본값**을 정하는 치환 문법의 연산자를 채우세요.', '콜론과 빼기 기호예요.', NULL, NULL, '[]', 'fill', '[":-", ":?", ":+", "=>"]', NULL, '`:-` 는 기본값, `:?` 는 필수 표시입니다.', '[0]', 'GREETING: ${GREETING{0}hello}', NULL, NULL),
  (175, 16, '필수 변수', '변수가 없으면 **오류로 멈추게** 하는 치환 문법의 연산자를 채우세요.', '콜론과 물음표예요.', NULL, NULL, '[]', 'fill', '[":?", ":-", ":+", "?:"]', NULL, '오류 메시지에 `MUSTHAVE is required` 가 함께 나옵니다.', '[0]', 'MUSTHAVE: ${MUSTHAVE{0}MUSTHAVE is required}', NULL, NULL),
  (175, 17, '프로젝트 이름', '프로젝트 이름을 **직접 정하는** 옵션을 채우세요.', '"project"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-p", "-n", "-f", "-c"]', NULL, '`-f` 는 compose 파일을 정하는 옵션입니다.', '[0]', 'docker compose {0} myproj up -d', NULL, NULL),
  (175, 18, '프로파일 켜기', '`debug` 프로파일의 서비스를 **함께 켜는** 옵션을 채우세요.', '"프로파일"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--profile", "--tag", "--with", "--env"]', NULL, '환경 변수 `COMPOSE_PROFILES` 로도 켤 수 있습니다.', '[0]', 'docker compose {0} debug up -d tool', NULL, NULL),
  (175, 19, '서비스 개수 늘리기', '서비스 `web` 의 컨테이너를 **3개로 늘리는** 옵션을 채우세요.', '"규모"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--scale", "--count", "--replicas", "--size"]', NULL, '컨테이너 이름은 `프로젝트-web-1`, `-2`, `-3` 이 됩니다.', '[0]', 'docker compose up -d {0} web=3', NULL, NULL),
  (175, 20, '일회성 컨테이너 자동 삭제', '`docker compose run` 으로 만든 컨테이너를 **끝난 뒤 자동 삭제**하는 옵션을 채우세요.', '"remove"의 줄임이에요.', NULL, NULL, '[]', 'fill', '["--rm", "--del", "--once", "--clean"]', NULL, '옵션이 없으면 `Exited` 상태로 남습니다.', '[0]', 'docker compose run {0} early echo hi', NULL, NULL),
  (175, 21, '강제로 다시 만들기', '설정이 바뀌지 않았어도 컨테이너를 **다시 만들게** 하는 `up` 옵션을 채우세요.', '"강제"와 "다시 만들기"를 이어 붙인 이름이에요.', NULL, NULL, '[]', 'fill', '["--force-recreate", "--rebuild", "--refresh", "--reset"]', NULL, '`Recreate` → `Recreated` 가 표시됩니다.', '[0]', 'docker compose up -d {0} early', NULL, NULL),
  (175, 22, '고아 컨테이너 정리', '파일에 없는 서비스의 컨테이너를 **함께 정리**하는 `down` 옵션을 채우세요.', '"고아 제거"를 이어 붙인 이름이에요.', NULL, NULL, '[]', 'fill', '["--remove-orphans", "--clean", "--prune", "--orphans"]', NULL, '파일에 없는 서비스의 컨테이너까지 함께 내려갑니다.', '[0]', 'docker compose down {0}', NULL, NULL),
  (175, 23, '프로젝트 목록', '실행 중인 compose **프로젝트 목록**을 보는 하위 명령을 채우세요.', '"list"의 줄임이에요.', NULL, NULL, '[]', 'fill', '["ls", "ps", "list-all", "projects"]', NULL, '`ps` 는 한 프로젝트의 컨테이너를 보여 줍니다.', '[0]', 'docker compose {0}', NULL, NULL),
  (175, 24, '준비될 때까지 기다리는 조건', '`depends_on` 에서 대상 서비스가 **healthy 가 될 때까지 기다리는** 조건 값을 채우세요.', '"서비스"와 "건강한"을 이어 붙인 이름이에요.', NULL, NULL, '[]', 'fill', '["service_healthy", "service_ready", "service_up", "healthy"]', NULL, '대상 서비스에 healthcheck 가 있어야 합니다.', '[0]', 'condition: {0}', NULL, NULL),
  (175, 25, '환경 변수 파일', '서비스의 **환경 변수를 파일에서 읽어 오는** compose 키 이름을 채우세요.', '"env"와 "file"을 밑줄로 이어요.', NULL, NULL, '[]', 'fill', '["env_file", "envfile", "dotenv", "env"]', NULL, '같은 변수가 `environment` 에도 있으면 `environment` 가 우선합니다.', '[0]', '{0}: app.env', NULL, NULL),
  (175, 26, '변수 우선순위 확인하기', 'compose 파일의 `${GREETING:-hello-default}` 가 어떤 값으로 치환되는지 단계별로 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '기본값 → .env → 쉘 변수 → 컨테이너 확인 순서예요.', NULL, NULL, '[]', 'order', '["`.env` 도 쉘 변수도 없이 `docker compose config` 로 기본값 `hello-default` 가 쓰이는지 본다", "`.env` 에 `GREETING=from-dotenv` 를 적고 `docker compose config` 로 값이 바뀌는지 본다", "`GREETING=from-shell docker compose config` 로 쉘 변수가 `.env` 보다 우선하는지 본다", "`docker compose up -d` 후 `docker compose exec 서비스 printenv GREETING` 으로 컨테이너 안의 최종 값을 확인한다"]', NULL, '`config` 는 실제로 컨테이너를 만들지 않으므로 값을 안전하게 확인할 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (175, 27, 'DB 가 준비된 뒤에 앱 시작하기', '앱이 DB 가 준비된 뒤에만 시작되게 설정하고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', 'healthcheck → 조건 → 올리기 → 시각 확인 순서예요.', NULL, NULL, '[]', 'order', '["`db` 서비스에 `healthcheck` 를 정의한다", "앱 서비스에 `depends_on` 의 `db` 에 `condition: service_healthy` 를 쓴다", "`docker compose up -d` 로 올린다", "`docker inspect` 의 `StartedAt` 으로 앱이 `db` 가 healthy 가 된 뒤에 시작되었는지 확인한다"]', NULL, 'healthcheck 없이 `service_healthy` 를 쓰면 설정 오류가 납니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (175, 28, '디버그용 서비스 켜기', '평소에는 꺼 두고 필요할 때만 켜는 디버그 서비스를 다루는 순서입니다. 순서에 맞게 놓아 보세요.', '프로파일 지정 → 기본 실행 → 켜기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["디버그 서비스에 `profiles: [debug]` 를 쓴다", "`docker compose up -d` 로 올리고 `docker compose ps` 에 디버그 서비스가 없는 것을 확인한다", "`docker compose --profile debug up -d tool` 로 디버그 서비스를 켠다", "`docker compose ps` 에 `tool` 이 실행 중으로 보이는지 확인한다"]', NULL, '일상 운영 서비스와 디버깅 도구를 한 파일에 두면서도 평소에는 영향을 주지 않게 할 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (175, 29, '고아 컨테이너 정리하기', 'compose 파일에서 서비스를 지운 뒤 남은 컨테이너를 정리하는 순서입니다. 순서에 맞게 놓아 보세요.', '파일 수정 → 경고 확인 → 정리 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["compose 파일에서 필요 없는 서비스를 지운다", "`docker compose up -d` 를 하고 `Found orphan containers` 경고가 나오는지 확인한다", "`docker compose down --remove-orphans` 로 정리한다", "`docker ps -a` 로 그 프로젝트의 불필요한 컨테이너가 남지 않았는지 확인한다"]', NULL, '`down --remove-orphans` 는 프로젝트의 컨테이너를 모두 내리니 계속 쓸 서비스가 있다면 다시 `up -d` 로 올리세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
